    "python tools/cli.py query 'validation rules'",
    "python tools/cli.py vector-cleanup --apply",
    "python tools/cli.py bundle --target FORM0000",
    "python tools/cli.py dependencies --target FORM0000 --direction both",
    "python tools/cli.py rules search 'validation'",
    "python tools/cli.py workflow start --name codify-form --target FORM0000",
    "python tools/cli.py workflow end 'feat: analyzed FORM0000'",
    "python tools/cli.py workflow cleanup"
  ],
  "commands": {
    "vector_database": {
      "ingest": "Ingest files into Vector DB (--full, --incremental, --hours, --cleanup)",
      "query": "Semantic search against Vector DB + RLM cache",
