    },
    "context_bundling": {
      "init-context": "Initialize manifest and generate bundle",
      "manifest": "Manage context manifests (init, add, remove, bundle)",
      "bundle": "Gather comprehensive context for artifact"
    },
    "analysis_investigation": {
      "scan": "Scan Oracle Forms artifact for business rules",
      "dependencies": "Query artifact dependencies (upstream/downstream)",
      "investigate": "Deep dive tools (code, library, lineage)",
      "applications": "Trace upstream to find parent applications"
    },
    "business_rules_workflows": {
      "rules": "Discover and manage business rules",
      "roles": "Role verification (verify, scan)",
      "br": "Business Rules Inventory manager",
      "bw": "Business Workflows Inventory manager"
    },
    "tools_workflows": {
      "tools": "Discover and manage CLI tools (list, search, add)",
      "workflow": "Agent lifecycle (start, retrospective, end, cleanup)"
    },
    "menu_config": {
      "menu": "Menu configuration tools (rebuild, find, add, query)",
      "config": "Update form rules (TS)"
    }
  },
  "inputs": ["Various inventory JSON files", "Manifest files", "Oracle Forms XML/MD"],
  "outputs": ["Context bundles", "Dependency reports", "Business rule files"],
  "dependencies": ["dependencies.py", "workflow_manager.py", "ingest.py", "cleanup.py"],
  "consumed_by": ["All /codify-* and /investigate-* workflows"],
